select jsonb_build_object(
 'columns',(select jsonb_agg(x) from(select table_name,column_name,data_type,udt_name,is_nullable,column_default from information_schema.columns where table_schema='zoi' and table_name in('feed_posts','feed_comments','feed_likes','user_profiles') order by table_name,ordinal_position)x),
 'constraints',(select jsonb_agg(x) from(select c.relname,con.conname,pg_get_constraintdef(con.oid) as definition from pg_constraint con join pg_class c on c.oid=con.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='zoi' and c.relname in('feed_posts','feed_comments','feed_likes','user_profiles'))x),
 'policies',(select jsonb_agg(x) from(select * from pg_policies where schemaname='zoi' and tablename in('feed_posts','feed_comments','feed_likes','user_profiles'))x),
 'functions',(select jsonb_agg(x) from(select n.nspname,p.proname,pg_get_function_identity_arguments(p.oid) as arguments,pg_get_functiondef(p.oid) as definition,p.proacl from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','zoi') and p.proname in('feed_list','feed_post','feed_post_as','feed_like','feed_comment','feed_comments_list','feed_delete','ensure_profile'))x),
 'crypto_schema',(select n.nspname from pg_extension e join pg_namespace n on n.oid=e.extnamespace where e.extname='pgcrypto'),
 'qa_identity',(select jsonb_build_object('auth_id',u.id,'email_confirmed',u.email_confirmed_at is not null,'owns_qa_workspace',exists(select 1 from zoi.workspace_members m join zoi.user_profiles p on p.id=m.profile_id where p.auth_user_id=u.id and p.id='21a04e78-e3b1-448e-8517-47aad25dd5da' and m.workspace_id='053a5656-b19b-48a4-8721-65c4674f647c' and m.role='owner')) from auth.users u where u.id='2ba5b8e3-4fe9-4ec7-a3bf-7f616fcf07fd')
) as community_review;
